  $hash=hash('sha256',wp_json_encode($p));$t=AIM_Trading::table('workshop');$e=AIM_Trading::table('workshop_events');$a=AIM_Trading::table('accounts');$l=AIM_Trading::table('ledger');
  $prior=$wpdb->get_row($wpdb->prepare("SELECT * FROM $e WHERE user_id=%d AND request_id=%s",$uid,$req),ARRAY_A);if($wpdb->last_error)return AIM_Trading::error('Chưa kiểm tra được kết quả.',503);if($prior)return $prior['payload_hash']===$hash?array('replayed'=>true,'events'=>json_decode($prior['events'],true)):AIM_Trading::error('Mã yêu cầu đã dùng cho nội dung khác.',409);
