   elseif(in_array($type,array('article_review','article_revoke'),true)){
    $id=(string)($p['id']??'');$article=$state['articles'][$id]??null;$status=$type==='article_revoke'?'revoked':($p['status']??'');$reason=AIM_Workshop_Engine::clean($p['reason']??'',1000);AIM_Workshop_Engine::need($article&&strlen($reason)>=10,'Cần bài viết và lý do cụ thể.');
