     if($status==='approved'){foreach($wpdb->get_results("SELECT user_id,state FROM $t WHERE user_id>0",ARRAY_A)?:array() as $other){foreach((json_decode($other['state'],true)['articles']??array()) as $oa)if((int)$other['user_id']!==$uid&&$oa['hash']===$article['hash']&&$oa['status']==='approved')throw new RuntimeException('Nội dung trùng bài đã được thưởng ở tài khoản khác.');}if($wpdb->last_error)throw new RuntimeException('Chưa kiểm tra được bài trùng.');}
    }$state['articles'][$id]['status']=$status;$state['articles'][$id]['reason']=$reason;$state['articles'][$id]['reviewer']=$actor;$state['articles'][$id]['reviewed_at']=$at;$state['articles'][$id]['reward']=$status==='approved'?100:0;$result=array('state'=>$state,'delta'=>$delta,'events'=>array(array('kind'=>$type,'article_id'=>$id,'status'=>$status,'reason'=>$reason,'cash_delta'=>$delta,'at'=>$at)));
   }else $result=AIM_Workshop_Engine::apply($state,$p,$at);
   $delta=$result['delta'];$reserved=AIM_Limit_Orders::reserved($uid);AIM_Workshop_Engine::need((int)$spot['cash']-$reserved['cash']+$delta>=0,'AIM khả dụng không đủ; khoản giữ cho lệnh không được dùng mua.');AIM_Workshop_Engine::need((int)$pool['cash']-$delta>=0,'Quỹ thử nghiệm chưa đủ trả thưởng. Thử lại sau.');
