 static function people(){global $wpdb;$out=array();foreach($wpdb->get_results('SELECT user_id,state FROM '.AIM_Trading::table('workshop').' ORDER BY user_id DESC LIMIT 100',ARRAY_A)?:array() as $row){$s=json_decode($row['state'],true);if(empty($s['profile']['public']))continue;$out[]=array('id'=>(int)$row['user_id'],'nickname'=>$s['profile']['nickname']?:'Người học AIM','bio'=>$s['profile']['bio'],'theme'=>$s['active_theme'],'avatar'=>$s['avatar']??'compass','frame'=>$s['active_frame']??'none','badges'=>!empty($s['profile']['show_badges'])?array_keys($s['completed']):array());}return $out;}
 static function refund_queue(){global $wpdb;$out=array();foreach($wpdb->get_results('SELECT user_id,revision,state FROM '.AIM_Trading::table('workshop').' WHERE user_id>0 ORDER BY updated DESC',ARRAY_A)?:array() as $row){$s=json_decode($row['state'],true);foreach($s['purchases']??array() as $id=>$purchase)if($purchase['status']==='pending')$out[]=array_merge($purchase,array('scenario'=>$id,'user_id'=>(int)$row['user_id'],'revision'=>(int)$row['revision']));}if($wpdb->last_error)return AIM_Trading::error('Chưa đọc được hàng chờ hoàn tiền.',503);return $out;}
 static function review_queue(){global $wpdb;$out=array();foreach($wpdb->get_results('SELECT user_id,revision,state FROM '.AIM_Trading::table('workshop').' ORDER BY updated DESC LIMIT 100',ARRAY_A)?:array() as $row){$s=json_decode($row['state'],true);foreach($s['articles'] as $article)if(in_array($article['status'],array('pending','approved'),true))$out[]=array_merge($article,array('user_id'=>(int)$row['user_id'],'revision'=>(int)$row['revision']));}return $out;}
 static function stats(){
  global $wpdb;$e=AIM_Trading::table('workshop_events');$total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $e WHERE test_account=0 AND user_id>0");$out=array('pilot_excluded'=>true,'live_events'=>$total,'pilot_events'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $e WHERE test_account=1"),'metrics'=>null,'notice'=>'Chỉ số học tập từ sự kiện máy chủ, loại tài khoản thử. Tuần 1 là ngày 7–13; tuần 4 là ngày 28–34 sau lượt đầu. Chỉ tính cohort đủ thời gian quan sát. Chưa đo lượt đọc bài/video và lỗi yêu cầu.');
  if($total>10000){$out['notice']='Vượt giới hạn tổng hợp bản thử 10.000 sự kiện. Cần bảng tổng hợp trước khi công bố chỉ số.';return $out;}
  $rows=$wpdb->get_results("SELECT user_id,events FROM $e WHERE test_account=0 AND user_id>0 ORDER BY id",ARRAY_A);if($wpdb->last_error)return AIM_Trading::error('Chưa đọc được chỉ số.',503);
  $m=array('learners'=>0,'starts'=>0,'completions'=>0,'second_players'=>0,'earned'=>0,'spent'=>0,'refunded'=>0,'revoked'=>0,'week1'=>array('eligible'=>0,'returned'=>0,'rate'=>null),'week4'=>array('eligible'=>0,'returned'=>0,'rate'=>null));$users=array();
  foreach($rows?:array() as $row)foreach(json_decode($row['events'],true)?:array() as $ev){$kind=$ev['kind'];$uid=$row['user_id'];$delta=$ev['cash_delta']??0;if($delta>0){if($kind==='refund_review')$m['refunded']+=$delta;else $m['earned']+=$delta;}if(in_array($kind,array('buy_theme','buy_frame','unlock'),true))$m['spent']-=$delta;if($kind==='article_revoke')$m['revoked']-=$delta;if($kind==='start_run'){$m['starts']++;if(!isset($users[$uid]))$users[$uid]=array('first'=>$ev['at'],'starts'=>0,'activity'=>array());$users[$uid]['starts']++;}if(in_array($kind,array('start_run','step'),true)&&isset($users[$uid]))$users[$uid]['activity'][]=$ev['at'];if($kind==='step'&&!empty($ev['finished']))$m['completions']++;}
  $now=microtime(true)*1000;$day=86400000;$m['learners']=count($users);foreach($users as $u){if($u['starts']>=2)$m['second_players']++;foreach(array('week1'=>7,'week4'=>28) as $key=>$offset){if($now<$u['first']+($offset+7)*$day)continue;$m[$key]['eligible']++;foreach($u['activity'] as $at)if($at>=$u['first']+$offset*$day&&$at<$u['first']+($offset+7)*$day){$m[$key]['returned']++;break;}}}foreach(array('week1','week4') as $key)if($m[$key]['eligible'])$m[$key]['rate']=$m[$key]['returned']/$m[$key]['eligible'];$out['metrics']=$m;return $out;
 }
