 static function allow_open($market,$locked=false){global $wpdb;if(!self::ready())return true;$row=$wpdb->get_row('SELECT state FROM '.AIM_Trading::table('workshop').' WHERE user_id=0'.($locked?' FOR UPDATE':''),ARRAY_A);if($wpdb->last_error)return false;$state=$row?json_decode($row['state'],true):array();return is_array($state)&&($state['operations'][$market.'_open']??true)===true;}
 static function routes(){foreach(array('account','catalog','people','review_queue','refund_queue','stats','operations','leaderboard') as $method)register_rest_route('aim-trading/v1','/workshop/'.$method,array('methods'=>'GET','callback'=>array(__CLASS__,$method),'permission_callback'=>array('AIM_Trading',in_array($method,array('review_queue','refund_queue','stats','operations'),true)?'admin_permission':'permission')));register_rest_route('aim-trading/v1','/workshop/action',array('methods'=>'POST','callback'=>array(__CLASS__,'mutate'),'permission_callback'=>array('AIM_Trading','permission')));}
